func EventRelationExists(ctx context.Context, exec boil.ContextExecutor, childNid int64) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from \"event_relations\" where \"child_nid\"=$1 limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, childNid)
	}
	row := exec.QueryRowContext(ctx, sql, childNid)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "dbpostgres: unable to check if event_relations exists")
	}

	return exists, nil
}

// Exists checks if the EventRelation row exists.
func (o *EventRelation) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return EventRelationExists(ctx, exec, o.ChildNid)
}
